window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/natureza_2023.js"]=[{"title":"Plantas nativas alimentam polinizadores","steps":["As sementes ampliam a presença de plantas nativas.","Suas flores oferecem recursos como néctar e pólen às abelhas.","O mecanismo direto é aumentar alimento, D; outras medidas ambientais podem ajudar, mas não foram descritas."],"alternatives":{"A":"Semear plantas não demonstra redução direta dos predadores de abelhas.","B":"O método não informa substituição ou redução do uso de pesticidas.","C":"A competição por abrigo não é o processo diretamente afetado pela floração.","D":"Mais plantas floríferas ampliam a disponibilidade de recursos alimentares.","E":"As sementes não criam diretamente locais de nidificação e reprodução."},"takeaway":"Relacione a intervenção ao recurso que ela disponibiliza diretamente ao organismo.","key":"natureza:N010","area":"natureza","year":2023,"number":91,"answer":"D","subject":"Biologia","topic":"Ecologia e impactos ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ferro e transporte de oxigênio","steps":["Ferro é componente essencial da hemoglobina das hemácias.","Sua deficiência pode causar anemia ferropriva, associada à palidez.","B identifica o objetivo histórico descrito. Isso não torna seguro pôr pregos no alimento nem substitui avaliação de saúde."],"alternatives":{"A":"Diarreia não é prevenida por acrescentar ferro de modo indiscriminado.","B":"A intenção é combater a carência de ferro associada a um tipo de anemia.","C":"Ferro não elimina os parasitos causadores de verminoses.","D":"Raquitismo se relaciona principalmente ao metabolismo de vitamina D, cálcio e fósforo.","E":"Febre amarela é uma infecção viral, não doença prevenida pela oferta de ferro."},"takeaway":"Reconhecer a ideia biológica de uma prática histórica não equivale a recomendá-la.","key":"natureza:N192","area":"natureza","year":2023,"number":92,"answer":"B","subject":"Biologia","topic":"Fisiologia humana e saúde","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A fonte de calor é nuclear, não fóssil","steps":["Nas usinas de fissão, reações nucleares liberam energia que aquece o sistema.","Não é necessário queimar carvão, petróleo ou gás para gerar esse calor.","E aponta essa característica sem negar resíduos radioativos e riscos de acidentes."],"alternatives":{"A":"Resíduos radioativos exigem manejo específico; não são facilmente recicláveis em geral.","B":"Desmatamento não é uma característica necessária nem a vantagem pedida.","C":"Chuva ácida se associa especialmente a emissões de combustão, não é o processo nuclear central.","D":"A geração não depende de lançar gases tóxicos como uma termelétrica fóssil.","E":"A energia das reações nucleares pode fornecer calor sem consumir combustíveis fósseis."},"takeaway":"Uma vantagem comparativa não elimina os outros impactos ambientais da fonte.","key":"natureza:N609","area":"natureza","year":2023,"number":93,"answer":"E","subject":"Física","topic":"Física moderna e nuclear","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Dureza envolve íons que formam incrustações","steps":["A obstrução decorre da formação de sais pouco solúveis.","Íons cálcio podem formar carbonato e sulfato com baixa solubilidade nas condições citadas.","É preciso medir cálcio: teste 1, alternativa A."],"alternatives":{"A":"O teste 1 acompanha cálcio, componente relevante da dureza e das incrustações.","B":"Cloreto não mede diretamente a concentração do cátion relacionado à dureza.","C":"Turbidez informa dispersão de partículas, não a concentração específica de cálcio.","D":"Coliformes indicam contaminação microbiológica, não dureza da água.","E":"Sólidos sedimentáveis não substituem a medida do íon que pode precipitar posteriormente."},"takeaway":"Diferencie o soluto inicialmente dissolvido das partículas que já estão em suspensão.","key":"natureza:N798","area":"natureza","year":2023,"number":94,"answer":"A","subject":"Química","topic":"Equilíbrio químico e pH","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Músculo vermelho sustenta metabolismo aeróbio","steps":["A rede vascular transporta oxigênio e nutrientes para fibras musculares.","Músculos vermelhos, ricos em mioglobina e mitocôndrias, sustentam esforço prolongado.","B associa a estrutura ao metabolismo elevado necessário à migração, não a um pico de velocidade."],"alternatives":{"A":"Executar manobras não é a função específica explicada pela vascularização abundante.","B":"O suprimento de oxigênio favorece produção aeróbia de ATP em atividade prolongada.","C":"A forma aerodinâmica não decorre diretamente da irrigação das fibras.","D":"Contrações rápidas e explosivas não são a principal especialização dessas fibras.","E":"O texto destaca distância, sem afirmar uma adaptação exclusiva a grandes altitudes."},"takeaway":"Em fisiologia, relacione vascularização, oxigênio e metabolismo antes de olhar somente a velocidade.","key":"natureza:N154","area":"natureza","year":2023,"number":95,"answer":"B","subject":"Biologia","topic":"Citologia e bioquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O aumento de massa é a água incorporada","steps":["Um mol de CaCl₂ anidro tem 111 g.","A hidratação acrescenta dois mols de água: 2 × 18 = 36 g.","O ganho relativo é 36/111 × 100 ≈ 32,4%, próximo de 32%, D."],"alternatives":{"A":"14% não corresponde aos 36 g incorporados sobre os 111 g iniciais.","B":"16% aproxima usar apenas uma água, embora a fórmula indique duas.","C":"24% aproxima comparar com a massa final; ganho percentual usa a massa inicial.","D":"O quociente 36/111 fornece aproximadamente 32% de aumento.","E":"75% não resulta da razão entre água incorporada e sal anidro."},"takeaway":"Para ganho percentual, subtraia a massa inicial da final e divida pela inicial.","key":"natureza:N743","area":"natureza","year":2023,"number":96,"answer":"D","subject":"Química","topic":"Soluções e concentração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O recipiente retém o hormônio gasoso","steps":["O abacate libera etileno, hormônio envolvido no amadurecimento.","O recipiente fechado favorece seu acúmulo perto dos frutos.","A explica a aceleração; não é preciso eliminar o oxigênio."],"alternatives":{"A":"O etileno acumulado estimula o processo de amadurecimento do fruto.","B":"Fechar o recipiente não tem como mecanismo central reduzir a umidade.","C":"CO₂ não é o hormônio responsável pelo efeito descrito.","D":"A menor iluminação não explica especificamente a aceleração apresentada.","E":"Retirar oxigênio não é o procedimento e pode limitar a respiração."},"takeaway":"Identifique o sinal fisiológico que se acumula, e não apenas qualquer mudança no recipiente.","key":"natureza:N249","area":"natureza","year":2023,"number":97,"answer":"A","subject":"Biologia","topic":"Botânica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Cloroplastos funcionais fixam carbono","steps":["Os cloroplastos capturados mantêm parte da atividade fotossintética.","A energia luminosa sustenta a fixação de carbono que dá origem a compostos orgânicos.","O produto primário entre as opções é carboidrato, B; não se conclui autonomia alimentar completa da lesma."],"alternatives":{"A":"Ácidos nucleicos não são o produto primário destacado da fotossíntese.","B":"A fixação de carbono permite produzir açúcares e outros carboidratos.","C":"Proteínas exigem vias biossintéticas adicionais e não são o produto primário pedido.","D":"Vitaminas não resumem o produto carbonado básico da fotossíntese.","E":"Lipídios podem derivar de metabolismo posterior, mas não são a resposta primária."},"takeaway":"Fotossíntese fornece carbono orgânico; incorporar cloroplastos não transforma o animal numa planta.","key":"natureza:N155","area":"natureza","year":2023,"number":98,"answer":"B","subject":"Biologia","topic":"Citologia e bioquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O vetor se alimenta de sangue","steps":["A transmissão é indireta e depende do inseto vetor.","Ao realizar hematofagia em um cão infectado, ele pode adquirir o parasito.","Entre os materiais listados, sangue corresponde a essa via, D; não é contágio direto pelo convívio com o cão."],"alternatives":{"A":"Urina não é a via de aquisição do parasito pelo vetor hematófago.","B":"Saliva canina não define a transmissão vetorial da leishmaniose.","C":"Fezes não correspondem ao material ingerido pelo inseto nessa transmissão.","D":"A alimentação sanguínea do vetor estabelece a relação com o material pedido.","E":"Secreção ocular pode acompanhar sinais, mas não é a via vetorial indicada."},"takeaway":"Diferencie hospedeiro reservatório, parasito e vetor para reconhecer a via de transmissão.","key":"natureza:N271","area":"natureza","year":2023,"number":99,"answer":"D","subject":"Biologia","topic":"Zoologia e parasitologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"No ponto mais alto, a gravidade continua","steps":["Na inversão da subida para a descida, a velocidade instantânea é nula.","A força gravitacional não desaparece, portanto a aceleração permanece para baixo.","A combinação correta é v = 0 e a ≠ 0 para baixo, C, no modelo sem resistência do ar."],"alternatives":{"A":"A velocidade é nula, mas a aceleração gravitacional não aponta para cima.","B":"No ponto máximo a velocidade não é ascendente e a aceleração não é zero.","C":"Repouso instantâneo coincide com aceleração gravitacional não nula para baixo.","D":"Nem velocidade nem aceleração apontam para cima nesse instante.","E":"O movimento descendente começa depois; no instante máximo a velocidade ainda é zero."},"takeaway":"Velocidade nula num instante não significa equilíbrio nem aceleração nula.","key":"natureza:N378","area":"natureza","year":2023,"number":100,"answer":"C","subject":"Física","topic":"Mecânica: cinemática e dinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O corpo lúteo regride ao fim do ciclo","steps":["Após a ovulação, o corpo lúteo secreta progesterona e estrógenos.","Sem manutenção da gestação, sua regressão reduz esses hormônios.","A explica a queda descrita no texto; o item não oferece diagnóstico individual para sintomas pré-menstruais."],"alternatives":{"A":"A regressão da estrutura secretora ovariana reduz a produção hormonal.","B":"Ocitocina não é o fator que mantém diretamente essa secreção ovariana.","C":"A ovulação precede a fase lútea e não equivale à sua regressão.","D":"O pico ovulatório de LH não é a causa direta da queda ao fim da fase lútea.","E":"Adrenalina não é o regulador ovariano central apresentado no ciclo."},"takeaway":"Reconstrua a sequência folículo, ovulação, corpo lúteo e regressão antes de associar hormônios.","key":"natureza:N193","area":"natureza","year":2023,"number":101,"answer":"A","subject":"Biologia","topic":"Fisiologia humana e saúde","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Álcool secundário origina cetona","steps":["A hexan-3-ona tem carbonila no carbono 3 de uma cadeia de seis carbonos.","Oxidar o álcool secundário nessa posição gera a cetona sem mudar o esqueleto.","O precursor é hexan-3-ol, C."],"alternatives":{"A":"Hexanal é aldeído terminal e sua oxidação usual forma ácido carboxílico.","B":"Hexan-1-ol é primário; não fornece diretamente carbonila no carbono 3.","C":"A oxidação do grupo OH secundário no carbono 3 produz hexan-3-ona.","D":"O composto insaturado indicado não é o álcool secundário correspondente à cetona.","E":"Ácido hexanoico já tem grupo carboxila e não se transforma assim na cetona."},"takeaway":"Mantenha a posição do grupo funcional ao relacionar álcool secundário e cetona.","key":"natureza:N675","area":"natureza","year":2023,"number":102,"answer":"C","subject":"Química","topic":"Química orgânica: funções e propriedades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O tubo leva o gameta até a oosfera","steps":["Em grupos dependentes de água externa, gametas flagelados precisam deslocar-se até a oosfera.","O tubo polínico conduz os gametas masculinos no interior de tecidos reprodutivos.","D elimina essa dependência para a fecundação nos grupos com esse mecanismo."],"alternatives":{"A":"Frutos protegem e ajudam a dispersar sementes, mas não conduzem gametas.","B":"Esporos existem também em plantas cuja fecundação depende de água externa.","C":"A semente é formada depois da fecundação, não é o meio de transporte do gameta.","D":"O tubo polínico permite conduzir gametas sem uma lâmina externa de água.","E":"Vasos conduzem água e solutos, não fazem o papel reprodutivo do tubo."},"takeaway":"Separe adaptações de transporte, proteção e dispersão da adaptação específica da fecundação.","key":"natureza:N250","area":"natureza","year":2023,"number":103,"answer":"D","subject":"Biologia","topic":"Botânica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O anel interrompe o transporte pelo floema","steps":["O floema leva açúcares das regiões produtoras às consumidoras.","Retirar um anel completo interrompe essa continuidade, embora o xilema interno possa inicialmente conduzir água.","As raízes deixam de receber nutrientes orgânicos e morrem, E."],"alternatives":{"A":"As folhas podem continuar fotossintetizando inicialmente; o bloqueio direto é de transporte.","B":"O xilema não é o tecido retirado com o anel externo de casca.","C":"Trocas gasosas não explicam especificamente a perda de continuidade do floema.","D":"O problema não é apenas deixar de formar brotos, mas perder nutrição das raízes.","E":"Sem fluxo de seiva elaborada pelo anel, as raízes ficam sem suprimento orgânico."},"takeaway":"No anelamento, diferencie o transporte de açúcares pelo floema do fluxo de água pelo xilema.","key":"natureza:N251","area":"natureza","year":2023,"number":105,"answer":"E","subject":"Biologia","topic":"Botânica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O RNA orienta a produção de um antígeno","steps":["A capa lipídica protege e facilita a entrega do RNAm.","No citoplasma, ribossomos traduzem sua sequência em proteína viral.","O reconhecimento desse antígeno desencadeia resposta imune, C, sem exigir incorporação ao DNA."],"alternatives":{"A":"A capa ajuda na entrega, mas não substitui a expressão do antígeno codificado.","B":"O RNAm não funciona capturando vírus e levando-os ao exterior.","C":"A tradução produz um antígeno que pode ser reconhecido pelo sistema imune.","D":"Disputar ribossomos não é o mecanismo que produz memória imunológica.","E":"O mecanismo descrito não envolve integração do RNAm ao genoma humano."},"takeaway":"A vacina fornece instrução temporária para um antígeno, não um genoma viral completo.","key":"natureza:N295","area":"natureza","year":2023,"number":106,"answer":"C","subject":"Biologia","topic":"Microbiologia e imunologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Enzimas permitem atravessar envoltórios","steps":["O acrossomo contém enzimas envolvidas na passagem pelos envoltórios do ovócito.","Inibi-las bloqueia a etapa de penetração antes da fusão das membranas.","D identifica o efeito imediato; os eventos posteriores também deixam de ocorrer, mas por consequência."],"alternatives":{"A":"A formação do pronúcleo masculino é posterior ao bloqueio de penetração.","B":"A mitose do zigoto ocorre depois da fecundação, não é a ação direta das enzimas.","C":"A conclusão da meiose depende da fecundação e é uma consequência posterior.","D":"As enzimas acrossômicas participam da passagem pela corona radiata e zona pelúcida.","E":"A fusão fica inviabilizada depois, mas não é o alvo direto da função enzimática citada."},"takeaway":"Quando várias etapas deixam de ocorrer, procure a primeira diretamente afetada pelo agente.","key":"natureza:N156","area":"natureza","year":2023,"number":107,"answer":"D","subject":"Biologia","topic":"Citologia e bioquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Fluxo magnético variável gera força eletromotriz","steps":["A corrente na bobina produz um campo magnético que varia no tempo.","A variação do fluxo através do fundo condutor induz correntes, segundo Faraday-Lenz.","Essas correntes aquecem a panela por efeito Joule: D identifica a origem indutiva."],"alternatives":{"A":"Não é o aquecimento por radiação que origina a corrente mencionada.","B":"A panela não precisa receber corrente por contato elétrico com o fogão.","C":"A alternativa não identifica a variação de fluxo magnético responsável pela indução descrita.","D":"A variação do campo magnético induz força eletromotriz e correntes no metal.","E":"Não é necessário um mecanismo de ressonância para explicar a corrente de indução."},"takeaway":"Separe a origem da corrente, por indução, da produção de calor, por efeito Joule.","key":"natureza:N587","area":"natureza","year":2023,"number":108,"answer":"D","subject":"Física","topic":"Magnetismo e indução","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma polia móvel dobra a carga para a mesma força","steps":["No tipo 1, uma corda sustenta a carga: F = M₁g.","No tipo 2, dois ramos de tensão F sustentam a polia móvel: 2F = M₂g.","Dividindo, M₂/M₁ = 2, alternativa D; as polias fixas apenas redirecionam a corda."],"alternatives":{"A":"Um quarto não corresponde aos dois ramos que sustentam a carga móvel.","B":"Um meio inverte a vantagem mecânica do aparelho com polia móvel.","C":"Massas iguais exigiriam forças diferentes nos dois arranjos.","D":"A mesma força sustenta o dobro da massa quando há dois ramos de sustentação.","E":"As polias fixas adicionais não multiplicam a vantagem para quatro."},"takeaway":"Conte os ramos que puxam a polia móvel, não o número total de rodas do sistema.","key":"natureza:N379","area":"natureza","year":2023,"number":109,"answer":"D","subject":"Física","topic":"Mecânica: cinemática e dinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O reagente limitante cria um patamar","steps":["Há 5,25/525 = 0,010 mol de sal de mercúrio, formando no máximo 4,72 g de Hg₂Cl₂.","Isso exige 0,020 mol de NaCl, ou 1,16 g; antes disso a massa cresce proporcionalmente.","A curva parte de zero e estabiliza perto de 1,2 g de NaCl e 4,7 g de produto: B."],"alternatives":{"A":"A curva atinge o patamar perto de 0,6 g, esquecendo os dois mols de NaCl.","B":"O patamar de 4,72 g só é alcançado quando cerca de 1,16 g de NaCl foi adicionado.","C":"A curva não estabiliza apesar de se esgotar o sal de mercúrio.","D":"A curva indica produto mesmo sem NaCl e não parte da origem.","E":"A curva também parte de produto não nulo e ultrapassa o limite estequiométrico."},"takeaway":"O máximo de produto depende do reagente que se esgota; excesso do outro não aumenta o rendimento teórico.","key":"natureza:N744","area":"natureza","year":2023,"number":110,"answer":"B","subject":"Química","topic":"Soluções e concentração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A atenuação reduz a amplitude","steps":["O som transmitido pelo barbante perde energia ao longo do percurso.","Com maior extensão, a atenuação é maior, mantidas as outras condições.","A amplitude diminui, C; altura é frequência, não intensidade sonora."],"alternatives":{"A":"Altura distingue grave e agudo e depende da frequência, não da energia perdida.","B":"O período da fonte não é reduzido por alongar o percurso de transmissão.","C":"A perda de energia ao longo do meio reduz a amplitude da vibração.","D":"A velocidade depende das propriedades do meio mantidas no modelo.","E":"Sem mudar frequência e velocidade do meio, não se reduz o comprimento de onda."},"takeaway":"Não use altura como sinônimo de volume: altura é frequência; intensidade se relaciona à amplitude.","key":"natureza:N456","area":"natureza","year":2023,"number":111,"answer":"C","subject":"Física","topic":"Ondulatória e acústica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A potência se distribui na superfície esférica","steps":["Converta 2,4 mW em 2,4 × 10⁻³ W.","A 10 m, a área é 4πr² ≈ 4 × 3 × 100 = 1 200 m².","I = P/A = 2,0 × 10⁻⁶ W/m², A, no limite de alcance do modelo."],"alternatives":{"A":"Dividir 0,0024 W por 1 200 m² fornece 0,000002 W/m².","B":"O valor é dez vezes maior que a intensidade no limite de 10 m.","C":"A conta não divide corretamente por 4πr² com π aproximado por 3.","D":"Esse valor é a potência em watts, não a potência por área.","E":"O resultado aumenta indevidamente e não considera a diluição espacial."},"takeaway":"Em emissão esférica, use área 4πr², converta mili e confira a unidade W/m².","key":"natureza:N458","area":"natureza","year":2023,"number":113,"answer":"A","subject":"Física","topic":"Ondulatória e acústica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O atrito reduz a tração necessária","steps":["A força máxima de atrito é μMg = 0,2 × 200 × 10 = 400 N.","Ao acelerar, a caixa precisa de 600 N para a frente: a corda 2 fornece 200 N; a 1 fica frouxa.","Ao frear, precisa de 1 000 N para trás: atrito e corda 1 fornecem 400 + 600 N. Portanto A."],"alternatives":{"A":"T₂ = 200 N ao acelerar e T₁ = 600 N ao frear completam as forças necessárias.","B":"Na frenagem é preciso subtrair a contribuição do atrito, não somá-la à tração.","C":"Ao acelerar, 600 N é a força total, não a tensão após a ajuda do atrito.","D":"A alternativa troca as cordas ativas e não usa corretamente o atrito horizontal.","E":"As tensões e a identificação das cordas contrariam os diagramas de forças."},"takeaway":"Determine primeiro o sentido da tendência de deslizamento e só então o atrito e a corda tensionada.","key":"natureza:N380","area":"natureza","year":2023,"number":114,"answer":"A","subject":"Física","topic":"Mecânica: cinemática e dinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Metais são acumulados, não destruídos","steps":["O aguapé absorve contaminantes metálicos da água.","Elementos químicos não são digeridos nem usados como combustível para desaparecer.","Eles se acumulam nos tecidos, B, exigindo destinação adequada da biomassa contaminada."],"alternatives":{"A":"Enzimas não destroem átomos de metais transformando-os em matéria não metálica.","B":"A absorção e retenção nos tecidos retiram metais da água, sem destruí-los.","C":"Estômatos não são uma via geral de eliminação desses contaminantes metálicos.","D":"Não há glândulas que metabolizem elementos metálicos e os façam desaparecer.","E":"Metais tóxicos não funcionam como fonte de energia metabólica da planta."},"takeaway":"Retirar um poluente da água pode transferi-lo para a biomassa: isso não equivale a destruí-lo.","key":"natureza:N011","area":"natureza","year":2023,"number":115,"answer":"B","subject":"Biologia","topic":"Ecologia e impactos ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Decompositores promovem a amonificação","steps":["A seta 2 liga detritos à amônia.","A decomposição transforma nitrogênio orgânico em formas amoniacais.","Sem o grupo decompositor, essa etapa deixa de ocorrer: B, enquanto outras setas representam processos diferentes."],"alternatives":{"A":"A etapa 1 corresponde à fixação de nitrogênio, não à decomposição dos detritos.","B":"A passagem de detritos a amônia é a amonificação realizada por decompositores.","C":"A etapa 3 oxida amônia a nitrito na nitrificação.","D":"A etapa 4 transforma nitrito em nitrato, também na nitrificação.","E":"A etapa 5 devolve nitrogênio gasoso à atmosfera por desnitrificação."},"takeaway":"Leia origem e destino de cada seta para distinguir fixação, amonificação, nitrificação e desnitrificação.","key":"natureza:N012","area":"natureza","year":2023,"number":116,"answer":"B","subject":"Biologia","topic":"Ecologia e impactos ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Converta a dose e use o tempo de cruzeiro","steps":["O tempo de cruzeiro é 80% de 1 000 h = 800 h.","A dose considerada é 2 μSv/h × 800 h = 1 600 μSv = 1,6 mSv.","Divida por 0,2 mSv por radiografia: 8, A. O cálculo usa a exposição de cruzeiro fornecida pelo item."],"alternatives":{"A":"1,6 mSv dividido por 0,2 mSv resulta em oito doses de referência.","B":"Dez ignora que o cruzeiro representa apenas 80% das horas.","C":"Oitenta decorre de erro de escala ou da conversão entre micro e mili.","D":"Cem não incorpora corretamente o tempo de cruzeiro e as unidades.","E":"Mil é o tempo máximo em horas, não o número de radiografias equivalentes."},"takeaway":"Iguale as unidades antes de comparar doses e não confunda taxa horária com dose acumulada.","key":"natureza:N610","area":"natureza","year":2023,"number":117,"answer":"A","subject":"Física","topic":"Física moderna e nuclear","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Octanagem favorecida pela ramificação","steps":["O combustível procurado deve ser hidrocarboneto saturado, com 8 a 12 carbonos e ramificado.","O 2,2,4-trimetilpentano tem oito carbonos e cadeia ramificada saturada.","Ele satisfaz os critérios, C; o item trabalha resistência à detonação, não apenas energia por massa."],"alternatives":{"A":"n-Decano tem dez carbonos, mas sua cadeia normal não oferece a ramificação pedida.","B":"n-Heptano tem sete carbonos e cadeia não ramificada.","C":"O composto III é o hidrocarboneto saturado ramificado de oito carbonos procurado.","D":"O composto IV contém dupla ligação, contrariando a saturação exigida.","E":"O composto V é um álcool, não um hidrocarboneto."},"takeaway":"Use todos os critérios do comando: função, saturação, número de carbonos e ramificação.","key":"natureza:N676","area":"natureza","year":2023,"number":118,"answer":"C","subject":"Química","topic":"Química orgânica: funções e propriedades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Gás ideal exige temperatura absoluta","steps":["Converta 650 °C para 923 K e 100 mL para 0,100 L.","P = nRT/V = 0,1 × 0,082 × 923 / 0,1.","O resultado é aproximadamente 75,7 atm, próximo de 76 atm, C."],"alternatives":{"A":"756 atm é dez vezes o valor obtido com 0,100 L e 0,1 mol.","B":"533 combina erros de unidade e não corresponde à temperatura absoluta.","C":"A equação com T em kelvin e V em litro fornece cerca de 76 atm.","D":"53 atm resulta de usar 650 diretamente, sem converter Celsius em kelvin.","E":"13 atm não satisfaz a equação de estado com os dados fornecidos."},"takeaway":"Em PV = nRT, confira simultaneamente a escala de temperatura e a unidade de volume usada em R.","key":"natureza:N624","area":"natureza","year":2023,"number":119,"answer":"C","subject":"Química","topic":"Química ambiental e separação de misturas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A lâmpada queimada aumenta a resistência do conjunto","steps":["Antes, cada trecho tem resistência equivalente r = R em paralelo com a resistência da lâmpada.","Quando L₂ abre, seu trecho fica apenas com R, maior que r; a resistência total aumenta.","A corrente da série diminui e a tensão em L₁ e L₃ também: ambas ficam menos intensas, C."],"alternatives":{"A":"A fonte mantém tensão total, mas a divisão de tensões muda após a queima.","B":"A resistência total aumenta, portanto não há aumento da corrente da série.","C":"Os dois conjuntos intactos recebem menor tensão e suas lâmpadas perdem brilho.","D":"L₁ e L₃ são idênticas e simétricas; não há razão para só uma mudar.","E":"A simetria dos conjuntos intactos impede uma aumentar e a outra diminuir."},"takeaway":"Um resistor em paralelo mantém o circuito fechado após a queima, mas não mantém automaticamente o brilho.","key":"natureza:N329","area":"natureza","year":2023,"number":120,"answer":"C","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Maior diferença de eletronegatividade","steps":["O item pede caráter iônico, avaliado pela diferença de eletronegatividade.","Com O = 3,44, as diferenças são K: 2,62; Ca: 2,44; Mg: 2,13; Zn: 1,79; Fe: 1,61.","O maior valor é do potássio, A. Não se está comparando apenas intensidade eletrostática por carga do cátion."],"alternatives":{"A":"K apresenta a maior diferença de eletronegatividade em relação ao oxigênio.","B":"Ca tem diferença 2,44, menor que a do potássio.","C":"Mg tem diferença 2,13, inferior à de K.","D":"Zn apresenta diferença 1,79, não a maior entre os metais.","E":"Fe tem a menor diferença da lista em relação ao oxigênio."},"takeaway":"Caráter iônico e energia de interação não são sinônimos: use o critério solicitado pelo item.","key":"natureza:N833","area":"natureza","year":2023,"number":121,"answer":"A","subject":"Química","topic":"Ligações e interações intermoleculares","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O vapor esfria e condensa","steps":["A água de aquecimento entra como vapor a 120 °C e sai líquida a 100 °C.","Há liberação de calor sensível na redução de temperatura e de calor latente na condensação.","D identifica as duas parcelas fornecidas ao produto; a evaporação do produto consome essa energia."],"alternatives":{"A":"A vaporização absorve energia e não é a única origem do calor fornecido pelo vapor.","B":"Condensar libera energia, mas a alternativa ignora o resfriamento de 120 a 100 °C.","C":"Troca a mudança de fase da fonte por vaporização, que consome calor.","D":"A fonte cede energia ao esfriar e ao passar de vapor a líquido.","E":"A vaporização do produto é destino do calor, não parcela adicional de sua origem."},"takeaway":"Escolha qual sistema você acompanha: a fonte condensa; a água do produto evapora.","key":"natureza:N500","area":"natureza","year":2023,"number":122,"answer":"D","subject":"Física","topic":"Termologia e termodinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Reconheça centros de quiralidade","steps":["No ibuprofeno, o carbono ligado ao grupo carboxila apresenta quatro substituintes diferentes.","Procure a mesma condição nas estruturas fornecidas, não apenas um anel ou heteroátomo.","O butilbrometo de escopolamina possui centros estereogênicos e apresenta isomeria óptica, E."],"alternatives":{"A":"A fenacetina representada não possui carbono tetraédrico com quatro grupos diferentes.","B":"O paracetamol não apresenta o centro quiral do tipo destacado no ibuprofeno.","C":"Na dipirona mostrada não se identifica o centro tetraédrico quiral pedido.","D":"A estrutura apresentada do diclofenaco não mostra o centro quiral do tipo considerado.","E":"A escopolamina representada possui centros quirais, inclusive com indicação espacial no desenho."},"takeaway":"Conte quatro grupos diferentes no carbono tetraédrico; anéis aromáticos não são, por si, centros quirais.","key":"natureza:N677","area":"natureza","year":2023,"number":123,"answer":"E","subject":"Química","topic":"Química orgânica: funções e propriedades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Inclua as paradas no tempo do carro","steps":["O caminhão leva 480/80 = 6 h = 360 min, sem paradas de cobrança.","O carro leva 480/100 = 4,8 h = 288 min, mais 10 × 3 = 30 min.","Seu total é 318 min, isto é, 42 min a menos: B."],"alternatives":{"A":"30 min é apenas o tempo que o carro perde nas dez cobranças.","B":"360 − (288 + 30) = 42 min é a vantagem final do carro.","C":"72 min seria a diferença sem considerar os pedágios pagos manualmente.","D":"288 min é só o tempo de movimento do carro.","E":"360 min é o tempo total do caminhão, não a diferença entre os veículos."},"takeaway":"Velocidade média do percurso deve incorporar paradas quando a pergunta pede tempo total.","key":"natureza:N381","area":"natureza","year":2023,"number":124,"answer":"B","subject":"Física","topic":"Mecânica: cinemática e dinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Combine gametas com um ou dois cromossomos 21","steps":["No modelo de segregação considerado, cada genitor trissômico pode formar gametas com um ou dois cromossomos 21.","As combinações são 1 + 1 = 2, 1 + 2 = 3 e 2 + 2 = 4.","Logo podem formar-se zigotos dissômicos, trissômicos ou tetrassômicos, E; isso não informa viabilidade ou chances iguais. Mulheres com síndrome de Down podem ser férteis: a frase generalizante do texto não deve ser adotada como regra clínica."],"alternatives":{"A":"Gametas com dois cromossomos também podem participar, então nem todos os zigotos são dissômicos.","B":"A tetrassomia só resulta da combinação 2 + 2, não de todas as combinações.","C":"A combinação 1 + 2 gera trissomia e não pode ser omitida.","D":"A combinação 1 + 1 permite dissomia e não pode ser excluída.","E":"Os três totais possíveis no modelo são dois, três e quatro cromossomos 21."},"takeaway":"Possibilidade de formação de zigotos não é o mesmo que nascimento viável ou probabilidade clínica individual.","key":"natureza:N104","area":"natureza","year":2023,"number":125,"answer":"E","subject":"Biologia","topic":"Genética e biotecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Protonar a amina aumenta o caráter iônico","steps":["A amina R₃N recebe H⁺ e forma R₃NH⁺, acompanhado de Cl⁻.","O sal interage melhor com o meio aquoso por solvatação dos íons.","A conversão aumenta o caráter iônico, C, sem alongar a cadeia nem realizar uma oxirredução."],"alternatives":{"A":"A protonação produz o ácido conjugado, não aumenta simplesmente a basicidade da amina.","B":"Maior caráter iônico não corresponde a maior afinidade por ambientes lipídicos.","C":"A presença do íon amônio favorece interações íon-dipolo com a água.","D":"O esqueleto carbônico R permanece na conversão apresentada.","E":"A reação ácido-base não altera os estados de oxidação como uma reação redox."},"takeaway":"Uma forma salina pode aumentar solubilidade aquosa sem modificar a cadeia carbônica do fármaco.","key":"natureza:N824","area":"natureza","year":2023,"number":126,"answer":"C","subject":"Química","topic":"Cinética química","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O bloqueio impede reoxidar o NADH","steps":["O NADH entrega elétrons à cadeia e se converte em NAD⁺.","Ao bloquear a etapa final, o fluxo de elétrons é comprometido e os transportadores reduzidos se acumulam.","A concentração de NADH aumenta, C, enquanto a produção oxidativa de ATP diminui."],"alternatives":{"A":"O bloqueio reduz o gradiente e a produção oxidativa de ATP, não a aumenta.","B":"A formação de água na etapa terminal fica comprometida.","C":"Sem conseguir transferir elétrons normalmente, o NADH deixa de ser reoxidado e se acumula.","D":"O metabolismo oxidativo não passa a produzir mais CO₂ por esse bloqueio.","E":"Inibir uma enzima não significa aumentar sua concentração celular."},"takeaway":"Quando uma via é bloqueada, verifique o acúmulo de substratos e a redução dos produtos posteriores.","key":"natureza:N157","area":"natureza","year":2023,"number":127,"answer":"C","subject":"Biologia","topic":"Citologia e bioquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O receptor pode captar sinais no mesmo canal","steps":["No modelo simplificado do item, o rádio seleciona uma frequência de comunicação.","Outro sinal na mesma frequência pode ser captado junto e prejudicar a recepção.","A resposta oficial é C. Ondas de frequências diferentes também se superpõem fisicamente; a condição do item se refere à recepção seletiva idealizada, não a uma regra universal de interferência."],"alternatives":{"A":"As ondas de rádio são eletromagnéticas, não precisam ser audíveis.","B":"Potências iguais não são condição necessária para um sinal atrapalhar outro.","C":"Sinais na frequência selecionada pelo receptor podem competir na recepção do modelo.","D":"Intensidades iguais não são necessárias para produzir o problema.","E":"As ondas eletromagnéticas não precisam ter velocidades diferentes para se superpor."},"takeaway":"Diferencie superposição física de ondas e interferência prejudicial num canal de comunicação.","key":"natureza:N459","area":"natureza","year":2023,"number":128,"answer":"C","subject":"Física","topic":"Ondulatória e acústica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Um contaminante lipofílico prefere a gordura","steps":["O Aldrin tem baixa polaridade e alta persistência.","Substâncias pouco polares tendem a se distribuir melhor em fases lipídicas que em meios aquosos.","O leite tem teor de gorduras relevante entre os fluidos citados, justificando E no modelo do item."],"alternatives":{"A":"Enzimas da saliva não tornam o meio preferencial para o composto pouco polar.","B":"A presença de células sanguíneas não é o critério de afinidade química apresentado.","C":"Sais dissolvidos não favorecem especialmente a partição de um composto pouco polar.","D":"Ureia não confere à urina a afinidade lipídica solicitada.","E":"A fração gordurosa do leite favorece a presença do contaminante lipofílico."},"takeaway":"Semelhante dissolve semelhante é uma aproximação útil para comparar partição entre água e lipídios.","key":"natureza:N834","area":"natureza","year":2023,"number":129,"answer":"E","subject":"Química","topic":"Ligações e interações intermoleculares","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Açúcar aumenta a massa de solutos","steps":["As versões são comparadas com composição semelhante, exceto açúcar e adoçante.","Uma grande massa de açúcar acrescenta massa ao líquido em comparação à pequena massa de adoçante.","No modelo, a versão comum apresenta maior densidade, A, e não maior temperatura de congelamento."],"alternatives":{"A":"Para volumes comparáveis, a maior massa de soluto eleva a densidade da versão comum.","B":"A presença de açúcar não justifica concluir menor viscosidade.","C":"O enunciado não fornece maior quantidade de CO₂ dissolvido na versão comum.","D":"O açúcar representa massa de soluto maior, não menor.","E":"Mais partículas de soluto tendem a abaixar a temperatura de congelamento, não elevá-la."},"takeaway":"Densidade é massa por volume; não confunda massa de soluto com volume de gás.","key":"natureza:N745","area":"natureza","year":2023,"number":131,"answer":"A","subject":"Química","topic":"Soluções e concentração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Pressão acompanha a temperatura absoluta","steps":["A quantidade de gás e o volume permanecem constantes.","Da equação PV = nRT, P/T = nR/V é constante com T em kelvin.","Ao esfriar, pressão e temperatura diminuem numa relação linear crescente: gráfico E."],"alternatives":{"A":"O caminho em trechos horizontal e vertical não mantém P/T constante.","B":"Pressão constante durante a queda de temperatura contrariaria volume e quantidade fixos.","C":"A curva inversa faria a pressão aumentar durante o resfriamento.","D":"A reta de inclinação negativa também faria pressão aumentar quando T diminui.","E":"A reta crescente percorrida para baixo e à esquerda representa P proporcional a T."},"takeaway":"No gráfico P × T de um gás a volume fixo, use kelvin e procure proporcionalidade direta.","key":"natureza:N501","area":"natureza","year":2023,"number":132,"answer":"E","subject":"Física","topic":"Termologia e termodinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A cadeia normal facilita a biodegradação considerada","steps":["O texto atribui a persistência ao trecho hidrocarbônico ramificado.","Substituí-lo por cadeia normal facilita o ataque microbiano no modelo apresentado.","E conserva a parte polar necessária ao tensoativo e modifica a região problemática."],"alternatives":{"A":"Retirar a parte polar prejudica a função tensoativa e não resolve o critério pedido.","B":"O problema indicado é a ramificação, não apenas as ligações do anel aromático.","C":"Neutralizar a cabeça não remove as ramificações responsáveis pela dificuldade descrita.","D":"Mudar a carga da cabeça não torna normal a cadeia hidrocarbônica.","E":"A cadeia normal é a alteração coerente com o mecanismo de biodegradação considerado."},"takeaway":"Não generalize o modelo a toda molécula: identifique a modificação estrutural indicada pelo texto.","key":"natureza:N678","area":"natureza","year":2023,"number":133,"answer":"E","subject":"Química","topic":"Química orgânica: funções e propriedades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Micronúcleos guardam material cromossômico","steps":["Na divisão, fragmentos cromossômicos ou cromossomos atrasados podem não integrar o núcleo principal.","Esse material pode ser envolvido por membrana e originar um micronúcleo.","A origem é cromossômica, E; o fuso participa da segregação, mas não produz DNA."],"alternatives":{"A":"Nucléolos organizam a produção de componentes ribossômicos, não são a origem cromossômica pedida.","B":"Lisossomos atuam na digestão intracelular, não na segregação de cromossomos.","C":"Ribossomos traduzem proteínas e não contêm os fragmentos cromossômicos do teste.","D":"Mitocôndrias possuem DNA próprio, mas não são a origem dos micronúcleos do ensaio.","E":"Fragmentos ou cromossomos não incorporados ao núcleo principal podem formar micronúcleos."},"takeaway":"O teste de micronúcleos avalia danos cromossômicos e falhas de segregação, não a síntese de DNA pelo fuso.","key":"natureza:N105","area":"natureza","year":2023,"number":134,"answer":"E","subject":"Biologia","topic":"Genética e biotecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Subtraia os ecos e conte ida e volta","steps":["Os dois ecos percorrem o mesmo trecho rochoso superior.","A diferença de tempo, 1,1 − 0,5 = 0,6 s, corresponde ao percurso adicional no líquido.","Esse percurso é 2 × 450 = 900 m; v = 900/0,6 = 1 500 m/s, D."],"alternatives":{"A":"270 resulta de multiplicar distância por tempo, em vez de dividir.","B":"540 não corresponde à razão entre 900 m e 0,6 s.","C":"818 aproxima 900/1,1, sem retirar o tempo comum na rocha.","D":"O percurso adicional de ida e volta no líquido dividido pelo intervalo fornece 1 500 m/s.","E":"1 800 não usa corretamente a diferença de 0,6 s e os 900 m percorridos."},"takeaway":"Em dois ecos, subtrair os tempos pode eliminar um trajeto desconhecido comum.","key":"natureza:N460","area":"natureza","year":2023,"number":135,"answer":"D","subject":"Física","topic":"Ondulatória e acústica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"natureza/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2023.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
